"""matplotlib.projections.polar — polar projection stubs."""

from matplotlib.axes._axes import Axes
import numpy as _np


class PolarAxes(Axes):
    """Polar-projection axes — (θ in radians, r) instead of (x, y).
    Every setter stores its argument on the instance so getters return
    the user-supplied value (mirrors upstream's behaviour)."""

    name = 'polar'

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._theta_offset = 0.0
        self._theta_direction = 1   # 1 = ccw, -1 = cw
        self._r_label_position = 22.5
        self._rlim = (0.0, 1.0)
        self._thetalim = (0.0, 2 * _np.pi)
        self._rticks = None
        self._thetagrids = None
        self._rgrids = None
        self._rorigin = 0.0
        self._rscale = 'linear'

    def set_theta_offset(self, offset):
        self._theta_offset = float(offset)

    def get_theta_offset(self):
        return self._theta_offset

    def set_theta_direction(self, direction):
        # Upstream accepts: 1, -1, 'clockwise', 'anticlockwise',
        # 'counterclockwise'. Normalise to ±1.
        if isinstance(direction, str):
            direction = -1 if direction in ('clockwise', 'cw') else 1
        self._theta_direction = int(direction)

    def get_theta_direction(self):
        return self._theta_direction

    def set_thetalim(self, *args, **kwargs):
        if 'thetamin' in kwargs and 'thetamax' in kwargs:
            lo, hi = kwargs['thetamin'], kwargs['thetamax']
        elif len(args) == 2:
            lo, hi = args
        elif len(args) == 1 and hasattr(args[0], '__len__'):
            lo, hi = args[0]
        else:
            return self._thetalim
        self._thetalim = (float(lo), float(hi))
        return self._thetalim

    def get_thetalim(self):
        return self._thetalim

    def set_thetagrids(self, angles, labels=None, **kwargs):
        """Pin the angular grid lines to ``angles`` (in degrees)."""
        self._thetagrids = (list(angles),
                              list(labels) if labels is not None else None)
        return self._thetagrids

    def set_rgrids(self, radii, labels=None, **kwargs):
        self._rgrids = (list(radii),
                          list(labels) if labels is not None else None)
        return self._rgrids

    def set_rlabel_position(self, value):
        self._r_label_position = float(value)

    def set_rlim(self, *args, **kwargs):
        if 'bottom' in kwargs and 'top' in kwargs:
            lo, hi = kwargs['bottom'], kwargs['top']
        elif len(args) == 2:
            lo, hi = args
        elif len(args) == 1 and hasattr(args[0], '__len__'):
            lo, hi = args[0]
        else:
            return self._rlim
        self._rlim = (float(lo), float(hi))
        return self._rlim

    def get_rlim(self):
        return self._rlim

    def set_rmax(self, rmax):
        lo, _ = self._rlim
        self._rlim = (lo, float(rmax))

    def get_rmax(self):
        return self._rlim[1]

    def set_rmin(self, rmin):
        _, hi = self._rlim
        self._rlim = (float(rmin), hi)

    def get_rmin(self):
        return self._rlim[0]

    def set_rticks(self, ticks):
        self._rticks = list(ticks)

    def set_thetamin(self, thetamin):
        _, hi = self._thetalim
        # thetamin in degrees per upstream.
        self._thetalim = (_np.radians(float(thetamin)), hi)

    def set_thetamax(self, thetamax):
        lo, _ = self._thetalim
        self._thetalim = (lo, _np.radians(float(thetamax)))

    def set_theta_zero_location(self, loc, offset=0.0):
        """``loc`` is one of 'N', 'NW', 'W', 'SW', 'S', 'SE', 'E', 'NE'."""
        mapping = {'E': 0, 'N': _np.pi / 2, 'W': _np.pi, 'S': -_np.pi / 2,
                    'NE': _np.pi / 4, 'NW': 3 * _np.pi / 4,
                    'SW': -3 * _np.pi / 4, 'SE': -_np.pi / 4}
        self._theta_offset = mapping.get(loc, 0.0) + _np.radians(offset)

    def set_rscale(self, scale):
        self._rscale = str(scale)

    def get_rscale(self):
        return self._rscale


class PolarTransform:
    pass


class InvertedPolarTransform:
    pass


