from matplotlib.axis import Axis as _Axis, Tick as _Tick
from matplotlib.ticker import Locator as _Locator, Formatter as _Formatter


class ThetaAxis(_Axis):
    """The angular axis of a polar plot. Inherits the standard Axis
    surface; ``axis_name`` distinguishes it for code that needs to
    branch on which axis it's looking at."""
    __name__ = 'thetaaxis'
    axis_name = 'theta'


class RadialAxis(_Axis):
    """The radial axis of a polar plot."""
    __name__ = 'radialaxis'
    axis_name = 'radius'


class ThetaTick(_Tick):
    """A tick on the angular axis."""
    pass


class RadialTick(_Tick):
    """A tick on the radial axis."""
    pass


class ThetaLocator(_Locator):
    """Pick tick locations on the angular axis. Default to every 45°."""

    def __init__(self, base=None):
        self.base = base

    def __call__(self):
        return self.tick_values(0, 360)

    def tick_values(self, vmin, vmax):
        # Step that brings ~8 ticks into the [vmin, vmax] range.
        span = vmax - vmin
        step = 45.0 if span >= 180 else span / 8.0
        out, v = [], vmin
        while v <= vmax + 1e-9:
            out.append(v)
            v += step
        return out


class ThetaFormatter(_Formatter):
    """Format an angle in radians as a degrees string ("N°"). The shim
    assumes radians input."""

    def __call__(self, x, pos=None):
        import math
        deg = math.degrees(float(x))
        return f'{deg:.0f}°'


class RadialLocator(_Locator):
    """Pick tick locations on the radial axis. Falls back to numpy's
    default ``linspace`` heuristic with 5 ticks."""

    def __init__(self, base=None, axes=None):
        self.base = base
        self.axes = axes

    def __call__(self):
        return self.tick_values(0, 1)

    def tick_values(self, vmin, vmax):
        import numpy as _np
        return _np.linspace(vmin, vmax, 5).tolist()


class PolarAffine:
    """Affine transform tying angle/radius space to the unit circle.
    The plotly backend handles polar geometry natively, so this is
    purely a holder that records the underlying r-limits."""

    def __init__(self, scale_transform=None, limits=None):
        self.scale_transform = scale_transform
        self.limits = limits

    def transform(self, xy):
        import numpy as _np
        a = _np.asarray(xy, dtype=float)
        if a.ndim == 1:
            theta, r = a[0], a[1]
            return _np.array([r * _np.cos(theta), r * _np.sin(theta)])
        theta, r = a[:, 0], a[:, 1]
        return _np.column_stack([r * _np.cos(theta), r * _np.sin(theta)])

    def inverted(self):
        return InvertedPolarTransform()


