def _pa_get_rlabel_position(self): return self._r_label_position
def _pa_get_rorigin(self):         return getattr(self, '_rorigin', 0.0)
def _pa_set_rorigin(self, v):      self._rorigin = float(v)
def _pa_get_rsign(self):           return 1
def _pa_get_thetamin(self):        return getattr(self, '_thetamin', 0.0)
def _pa_get_thetamax(self):        return getattr(self, '_thetamax', 360.0)
def _pa_set_yscale(self, value, **kw): pass
def _pa_format_coord(self, theta, r): return f'θ={theta:g}, r={r:g}'

PolarAxes.get_rlabel_position = _pa_get_rlabel_position
PolarAxes.get_rorigin         = _pa_get_rorigin
PolarAxes.set_rorigin         = _pa_set_rorigin
PolarAxes.get_rsign           = _pa_get_rsign
PolarAxes.get_thetamin        = _pa_get_thetamin
PolarAxes.get_thetamax        = _pa_get_thetamax
PolarAxes.set_yscale          = _pa_set_yscale
PolarAxes.format_coord        = _pa_format_coord


# PolarTransform attributes
PolarTransform.input_dims  = 2
PolarTransform.output_dims = 2
PolarTransform.is_separable = False
def _pt_transform_non_affine(self, tr):
    import numpy as _np
    tr = _np.asarray(tr, dtype=float)
    if tr.ndim == 1: tr = tr.reshape(1, -1)
    theta, r = tr[:, 0], tr[:, 1]
    return _np.column_stack([r * _np.cos(theta), r * _np.sin(theta)])
def _pt_transform_path_non_affine(self, path):
    return path
def _pt_inverted(self): return InvertedPolarTransform()
PolarTransform.transform_non_affine      = _pt_transform_non_affine
PolarTransform.transform_path_non_affine = _pt_transform_path_non_affine
PolarTransform.inverted                  = _pt_inverted


# ─── Added: InvertedPolarTransform attrs ────────────────────────────


InvertedPolarTransform.input_dims = 2
InvertedPolarTransform.output_dims = 2

def _ipt_transform_non_affine(self, xy):
    import numpy as _np
    xy = _np.asarray(xy, dtype=float)
    if xy.ndim == 1: xy = xy.reshape(1, -1)
    x, y = xy[:, 0], xy[:, 1]
    return _np.column_stack([_np.arctan2(y, x), _np.hypot(x, y)])
def _ipt_inverted(self): return PolarTransform()

InvertedPolarTransform.transform_non_affine = _ipt_transform_non_affine
InvertedPolarTransform.inverted             = _ipt_inverted


# PolarAffine.get_matrix — return a 3×3 identity (no transformation
# applied at the affine stage; the polar→cartesian conversion happens
# in PolarTransform.transform_non_affine above).
def _polaff_get_matrix(self):
    import numpy as _np
    return _np.eye(3)
PolarAffine.get_matrix = _polaff_get_matrix


# Locator helpers — both ThetaLocator and RadialLocator inherit set_axis
# from the Locator base class, so attaching no-ops here would actually
# REGRESS behaviour (it'd silently overwrite the base impl). Instead,
# only attach `nonsingular` for RadialLocator (matches upstream).
def _rl_nonsingular(self, vmin, vmax):
    if vmin == vmax:
        return (vmin - 1.0, vmax + 1.0)
    if vmin > vmax:
        return (vmax, vmin)
    return (vmin, vmax)
RadialLocator.nonsingular = _rl_nonsingular
